insert into CK.tUserSimpleInvitation default values;

Test.Description:
-- SetupConfig: {}
create transformer
as
begin
  in all statement {insert into CK.tUserSimpleInvitation}
  begin
    add column FirstName = N'Albert';
  end
end

Test.ResultText:
insert into CK.tUserSimpleInvitation( CreatedById, FirstName ) values( @Options, N'Albert' );
select @Dummy
insert into CK.tUserSimpleInvitation( FirstName ) values( N'Albert' );

Test.Text:
insert into CK.tUserSimpleInvitation( CreatedById ) values( @Options );
set @InvitationIdResult = SCOPE_IDENTITY();
insert into CK.tUserSimpleInvitation( InvitationSendCount )
  select @Options;
select @InvitationTokenResult = InvitationToken from CK.tUserSimpleInvitation where InvitationId = @InvitationIdResult;
insert into CK.tUserSimpleInvitation( Options )
  select O from t;
insert into CK.tUserSimpleInvitation default values;

Test.Description:
-- SetupConfig: {}
create transformer
as
begin
  in each statement {insert into CK.tUserSimpleInvitation}
  begin
    add column FirstName = N'Albert';
  end
end

Test.ResultText:
insert into CK.tUserSimpleInvitation( CreatedById, FirstName ) values( @Options, N'Albert' );
set @InvitationIdResult = SCOPE_IDENTITY();
insert into CK.tUserSimpleInvitation( InvitationSendCount, FirstName )
  select @Options, N'Albert';
select @InvitationTokenResult = InvitationToken from CK.tUserSimpleInvitation where InvitationId = @InvitationIdResult;
insert into CK.tUserSimpleInvitation( Options, FirstName )
  select O, N'Albert' from t;
