Test.Text:
insert into CK.tUserSimpleInvitation( CreatedById, EMail, ExpirationDateUtc, InvitationSendCount, LastInvitationSendDate, Options )
      values( @ActorId, @EMail, @ExpirationDateUtc, @InvitationSendCount, @LastInvitationSendDate, @Options );
set @InvitationIdResult = SCOPE_IDENTITY();
select @InvitationTokenResult = InvitationToken from CK.tUserSimpleInvitation where InvitationId = @InvitationIdResult;

Test.Description:
-- SetupConfig: {}
create transformer
as
begin
  in single statement {insert into CK.tUserSimpleInvitation}
  begin
    add column FirstName = isnull(@FirstName,N'');
  end
end

Test.ResultText:
insert into CK.tUserSimpleInvitation( CreatedById, EMail, ExpirationDateUtc, InvitationSendCount, LastInvitationSendDate, Options , FirstName)
values( @ActorId, @EMail, @ExpirationDateUtc, @InvitationSendCount, @LastInvitationSendDate, @Options, isnull(@FirstName,N''));
set @InvitationIdResult = SCOPE_IDENTITY();
select @InvitationTokenResult = InvitationToken from CK.tUserSimpleInvitation where InvitationId = @InvitationIdResult;

